export const A3S_UI_TASK_PANE_SOURCE = "/* Task Pane */\n@layer components {\n  .task-pane {\n    display: flex;\n    width: min(100%, var(--task-pane-width, clamp(20rem, 28vw, 23.75rem)));\n    min-width: min(100%, var(--task-pane-min-width, 18.75rem));\n    max-width: 100%;\n    min-height: 0;\n    flex: none;\n    flex-direction: column;\n    overflow: hidden;\n  }\n\n  .task-pane > header,\n  .task-pane > footer {\n    display: flex;\n    flex: none;\n    align-items: center;\n    gap: 0.5rem;\n  }\n\n  .task-pane > header > :is(h2, h3, strong) {\n    min-width: 0;\n    flex: 1;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n  }\n\n  .task-pane > section {\n    min-width: 0;\n    min-height: 0;\n    flex: 1;\n    overflow: auto;\n  }\n\n  .task-pane > footer {\n    margin-block-start: auto;\n  }\n\n  @media (max-width: 56.25rem) {\n    .task-pane[data-responsive=\"overlay\"] {\n      position: absolute;\n      z-index: var(--task-pane-overlay-z-index, 20);\n      inset-block: 0;\n      inset-inline-end: 0;\n      width: min(\n        var(--task-pane-overlay-width, 23.75rem),\n        calc(100% - 2.25rem)\n      );\n      min-width: 0;\n      max-height: 100%;\n    }\n  }\n\n  @media (max-width: 32.5rem) {\n    .task-pane[data-responsive=\"overlay\"] {\n      inset-inline: 0;\n      width: 100%;\n    }\n  }\n}\n";
